const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, '..', '..', 'i18n', 'he');
const today = '2026-04-10';
const meta = { authors: ['Satoshi'], 'last-updated': today, locale: 'he' };

function write(name, data) {
	const file = path.join(dir, name);
	fs.writeFileSync(file, JSON.stringify(data, null, '\t') + '\n');
	console.log('Created', file);
}

// bank-runs
write('bank-runs_he.json', {
	'@metadata': meta,
	"bitcoin_doesnt_have_bank_runs": "\u05DC\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05D0\u05D9\u05DF \u05DE\u05E8\u05D5\u05E6\u05D9\u05DD \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7",
	"bank_runs_header": "\u05DC\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05D0\u05D9\u05DF \u05DE\u05E8\u05D5\u05E6\u05D9\u05DD \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7",
	"bank_runs_header_2": "\u05D0\u05D1\u05DC \u05DC\u05D1\u05E0\u05E7 \u05E9\u05DC\u05DA \u05D9\u05DB\u05D5\u05DC\u05D9\u05DD \u05DC\u05D4\u05D9\u05D5\u05EA",
	"bank_runs_what": "\u05DE\u05D4\u05D5 \u05DE\u05E8\u05D5\u05E5 \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7?",
	"bank_runs_what_content_1": "\u05DE\u05E8\u05D5\u05E5 \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7 \u05E7\u05D5\u05E8\u05D4 \u05DB\u05E9\u05D9\u05D5\u05EA\u05E8 \u05DE\u05D3\u05D9 \u05D0\u05E0\u05E9\u05D9\u05DD \u05DE\u05E0\u05E1\u05D9\u05DD \u05DC\u05DE\u05E9\u05D5\u05DA \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05D4\u05DD \u05DE\u05D4\u05D1\u05E0\u05E7 \u05D1\u05D0\u05D5\u05EA\u05D5 \u05D6\u05DE\u05DF.",
	"bank_runs_what_content_2": "\u05D0\u05DD \u05DC\u05D1\u05E0\u05E7\u05D9\u05DD \u05D0\u05D9\u05DF \u05DE\u05E1\u05E4\u05D9\u05E7 \u05DB\u05E1\u05E3 \u05D6\u05DE\u05D9\u05DF \u05DB\u05D3\u05D9 \u05DC\u05E2\u05DE\u05D5\u05D3 \u05D1\u05DE\u05E9\u05D9\u05DB\u05D5\u05EA, \u05D4\u05DD \u05E2\u05DC\u05D5\u05DC\u05D9\u05DD \u05DC\u05E7\u05E8\u05D5\u05E1 \u05DC\u05D7\u05DC\u05D5\u05D8\u05D9\u05DF \u05DB\u05E9\u05DE\u05E8\u05D5\u05E5 \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7 \u05E7\u05D5\u05E8\u05D4.",
	"bank_runs_how": "\u05D0\u05D9\u05DA \u05E7\u05D5\u05E8\u05D9\u05DD \u05DE\u05E8\u05D5\u05E6\u05D9\u05DD \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7?",
	"bank_runs_how_content_1": "\u05D4\u05DE\u05E2\u05E8\u05DB\u05EA \u05D4\u05D1\u05E0\u05E7\u05D0\u05D9\u05EA \u05E9\u05DC\u05E0\u05D5 \u05D4\u05D9\u05D0 '\u05E8\u05D6\u05E8\u05D1\u05D4 \u05D7\u05DC\u05E7\u05D9\u05EA' \u05DE\u05D4 \u05E9\u05D0\u05D5\u05DE\u05E8 \u05E9\u05D4\u05D1\u05E0\u05E7\u05D9\u05DD \u05DC\u05D0 \u05E4\u05E9\u05D5\u05D8 \u05E9\u05D5\u05DE\u05E8\u05D9\u05DD \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05DA \u05D1\u05DB\u05E1\u05E4\u05EA \u05D5\u05DE\u05D7\u05DB\u05D9\u05DD \u05E9\u05EA\u05D5\u05E6\u05D9\u05D0 \u05D0\u05D5\u05EA\u05D5 \u05D0\u05D5 \u05EA\u05DE\u05E9\u05D5\u05DA \u05D0\u05D5\u05EA\u05D5.",
	"bank_runs_how_content_2": "\u05D1\u05DE\u05E7\u05D5\u05DD \u05D6\u05D0\u05EA, \u05D4\u05D1\u05E0\u05E7 \u05E9\u05DC\u05DA \u05DC\u05D5\u05E7\u05D7 \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05DA \u05D5\u05DE\u05DC\u05D5\u05D5\u05D4 \u05D0\u05D5\u05EA\u05D5 \u05D0\u05D5 \u05DE\u05E9\u05E7\u05D9\u05E2 \u05D0\u05D5\u05EA\u05D5. \u05D6\u05D4 \u05D9\u05DB\u05D5\u05DC \u05DC\u05E0\u05E2\u05D5\u05DC \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05DA \u05DC\u05EA\u05E7\u05D5\u05E4\u05D5\u05EA \u05D0\u05E8\u05D5\u05DB\u05D5\u05EA, \u05DC\u05DE\u05E8\u05D5\u05EA \u05E9\u05D4\u05D1\u05E0\u05E7 \u05DE\u05D1\u05D8\u05D9\u05D7 \u05DC\u05DA \u05D0\u05EA \u05D4\u05D9\u05DB\u05D5\u05DC\u05EA \u05DC\u05DE\u05E9\u05D5\u05DA \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05DA \u05D1\u05DB\u05DC \u05E2\u05EA.",
	"bank_runs_how_content_3": "\u05D0\u05D6 \u05DE\u05D4 \u05E7\u05D5\u05E8\u05D4 \u05D0\u05DD \u05D0\u05EA\u05D4 \u05DE\u05E0\u05E1\u05D4 \u05DC\u05DE\u05E9\u05D5\u05DA \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05DA \u05D0\u05D7\u05E8\u05D9 \u05E9\u05D4\u05D1\u05E0\u05E7 \u05DB\u05D1\u05E8 \u05D4\u05DC\u05D5\u05D5\u05D4 \u05D0\u05D5\u05EA\u05D5 \u05D0\u05D5 \u05D4\u05E9\u05E7\u05D9\u05E2 \u05D0\u05D5\u05EA\u05D5?",
	"bank_runs_how_content_4": "\u05D6\u05D4 \u05DC\u05D0 \u05D1\u05E2\u05D9\u05D4 \u05D0\u05DD \u05D0\u05EA\u05D4 \u05D4\u05D9\u05D7\u05D9\u05D3 \u05E9\u05DE\u05E0\u05E1\u05D4 \u05DC\u05DE\u05E9\u05D5\u05DA. \u05D4\u05D1\u05E0\u05E7 \u05E4\u05E9\u05D5\u05D8 \u05D9\u05D9\u05E7\u05D7 \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC \u05DE\u05D9\u05E9\u05D4\u05D5 \u05D0\u05D7\u05E8 \u05D5\u05D9\u05D9\u05EA\u05DF \u05DC\u05DA \u05D0\u05D5\u05EA\u05D5 \u05D1\u05DE\u05E7\u05D5\u05DD. \u05D0\u05D1\u05DC \u05DE\u05D4 \u05E7\u05D5\u05E8\u05D4 \u05DB\u05E9\u05D9\u05D5\u05EA\u05E8 \u05DE\u05D3\u05D9 \u05D0\u05E0\u05E9\u05D9\u05DD \u05DE\u05E0\u05E1\u05D9\u05DD \u05DC\u05DE\u05E9\u05D5\u05DA \u05D1\u05D0\u05D5\u05EA\u05D5 \u05D6\u05DE\u05DF?",
	"bank_runs_how_content_5": "\u05D0\u05E0\u05E9\u05D9\u05DD \u05E8\u05D1\u05D9\u05DD \u05D1\u05D0\u05E8\u05D4\u05F4\u05D1 \u05D2\u05D9\u05DC\u05D5 \u05D0\u05EA \u05D6\u05D4 \u05DB\u05E9\u05D4\u05D9\u05D4 \u05DE\u05E8\u05D5\u05E5 \u05E2\u05DC Silicon Valley Bank \u05D1\u05DE\u05E8\u05E5 2023.",
	"bank_runs_how_content_6": "\u05D4\u05D1\u05E0\u05E7 \u05D4\u05E9\u05E7\u05D9\u05E2 \u05D0\u05EA \u05DB\u05E1\u05E4\u05D9 \u05D4\u05DC\u05E7\u05D5\u05D7\u05D5\u05EA \u05E9\u05DC\u05D5 \u05D1\u05D0\u05D2\u05E8\u05D5\u05EA \u05D7\u05D5\u05D1 \u05DE\u05DE\u05E9\u05DC\u05EA\u05D9\u05D5\u05EA \u05E9\u05D4\u05D9\u05D5 \u05E0\u05E2\u05D5\u05DC\u05D5\u05EA \u05DC\u05E2\u05D3 30 \u05E9\u05E0\u05D4. \u05D2\u05E8\u05D5\u05E2 \u05DE\u05DB\u05DA, \u05E2\u05E8\u05DA \u05D0\u05D2\u05E8\u05D5\u05EA \u05D4\u05D7\u05D5\u05D1 \u05D4\u05D0\u05DC\u05D4 \u05D9\u05E8\u05D3 \u05D1\u05D0\u05D5\u05E4\u05DF \u05D3\u05E8\u05DE\u05D8\u05D9 \u05DC\u05D0\u05D7\u05E8\u05D5\u05E0\u05D4, \u05D0\u05D6 Silicon Valley Bank \u05DC\u05D0 \u05D9\u05DB\u05DC \u05E4\u05E9\u05D5\u05D8 \u05DC\u05DE\u05DB\u05D5\u05E8 \u05D0\u05EA \u05D4\u05D0\u05D2\u05E8\u05D5\u05EA \u05DB\u05D3\u05D9 \u05DC\u05D4\u05D7\u05D6\u05D9\u05E8 \u05D0\u05EA \u05DB\u05E1\u05E4\u05D9 \u05D4\u05DE\u05E4\u05E7\u05D9\u05D3\u05D9\u05DD \u05E9\u05DC\u05D5. \u05D4\u05DD \u05D4\u05D9\u05D5 \u05D7\u05D3\u05DC\u05D9 \u05E4\u05D9\u05E8\u05E2\u05D5\u05DF. \u05DC\u05D0 \u05D4\u05D9\u05D4 \u05DC\u05D4\u05DD \u05DE\u05E1\u05E4\u05D9\u05E7 \u05DB\u05E1\u05E3 \u05DB\u05D3\u05D9 \u05DC\u05E2\u05DE\u05D5\u05D3 \u05D1\u05DE\u05E9\u05D9\u05DB\u05D5\u05EA \u05E9\u05DC \u05D4\u05DE\u05E4\u05E7\u05D9\u05D3\u05D9\u05DD \u05E9\u05DC\u05D4\u05DD.",
	"bank_runs_how_content_7": "\u05DB\u05DB\u05DC \u05E9\u05D9\u05D5\u05EA\u05E8 \u05D0\u05E0\u05E9\u05D9\u05DD \u05D2\u05D9\u05DC\u05D5, \u05D4\u05D1\u05E2\u05D9\u05D4 \u05E8\u05E7 \u05D4\u05D7\u05DE\u05D9\u05E8\u05D4. \u05E2\u05D5\u05D3 \u05D1\u05E7\u05E9\u05D5\u05EA \u05DC\u05DE\u05E9\u05D9\u05DB\u05D4 \u05D4\u05D2\u05D9\u05E2\u05D5, \u05D0\u05D1\u05DC \u05E8\u05D1\u05D5\u05EA \u05DE\u05D4\u05DF \u05DC\u05D0 \u05E2\u05D5\u05D1\u05D3\u05D5. \u05D0\u05DC\u05E4\u05D9 \u05E2\u05E1\u05E7\u05D9\u05DD \u05D4\u05D1\u05D9\u05E0\u05D5 \u05E9\u05DC\u05D0 \u05D9\u05D5\u05DB\u05DC\u05D5 \u05DC\u05E9\u05DC\u05DD \u05DE\u05E9\u05DB\u05D5\u05E8\u05D5\u05EA \u05DC\u05E2\u05D5\u05D1\u05D3\u05D9\u05D4\u05DD \u05D1\u05D2\u05DC\u05DC \u05DB\u05E9\u05DC\u05D5\u05DF \u05D4\u05D1\u05E0\u05E7.",
	"bank_runs_how_content_8": "\u05D4-FDIC \u05E0\u05DB\u05E0\u05E1 \u05D5\u05D4\u05E1\u05DB\u05D9\u05DD \u05DC\u05E4\u05E6\u05D5\u05EA \u05D0\u05EA \u05D4\u05DE\u05E4\u05E7\u05D9\u05D3\u05D9\u05DD. \u05D4\u05D1\u05E2\u05D9\u05D4 \u05E0\u05E4\u05EA\u05E8\u05D4? \u05DC\u05D0 \u05D1\u05D3\u05D9\u05D5\u05E7...",
	"bank_runs_fdic": "\u05D4\u05D0\u05DD \u05D1\u05D9\u05D8\u05D5\u05D7 FDIC \u05DE\u05D2\u05DF \u05E2\u05DC \u05D4\u05DB\u05E1\u05E3 \u05E9\u05DC\u05D9?",
	"bank_runs_fdic_content_1": "\u05D1\u05D9\u05D8\u05D5\u05D7 FDIC \u05E0\u05D5\u05E2\u05D3 \u05DC\u05D4\u05D2\u05DF \u05E2\u05DC \u05DE\u05E4\u05E7\u05D9\u05D3\u05D9 \u05D4\u05D1\u05E0\u05E7 \u05D1\u05DE\u05E7\u05E8\u05D4 \u05E9\u05D1\u05E0\u05E7 \u05E0\u05DB\u05E9\u05DC. \u05D4\u05E4\u05E7\u05D3\u05D5\u05EA \u05DE\u05D1\u05D5\u05D8\u05D7\u05D5\u05EA \u05E2\u05D3 $250,000 \u05DC\u05DE\u05E4\u05E7\u05D9\u05D3. \u05E0\u05E9\u05DE\u05E2 \u05DE\u05E6\u05D5\u05D9\u05DF, \u05E0\u05DB\u05D5\u05DF?",
	"bank_runs_fdic_content_2": "\u05DC\u05D0 \u05D1\u05D3\u05D9\u05D5\u05E7. \u05D0\u05DD \u05D1\u05E0\u05E7 \u05E0\u05DB\u05E9\u05DC, \u05DE\u05D0\u05D9\u05E4\u05D4 \u05D4-FDIC \u05DE\u05E7\u05D1\u05DC \u05D0\u05EA \u05D4\u05DB\u05E1\u05E3? \u05D9\u05E9 \u05DC\u05D4\u05DD \u05E7\u05E8\u05DF \u05D1\u05D9\u05D8\u05D5\u05D7 \u05E2\u05DD 125 \u05DE\u05D9\u05DC\u05D9\u05D0\u05E8\u05D3 \u05D3\u05D5\u05DC\u05E8.",
	"bank_runs_fdic_content_3": "\u05D6\u05D4 \u05E0\u05E9\u05DE\u05E2 \u05DB\u05DE\u05D5 \u05D4\u05E8\u05D1\u05D4 \u05DB\u05E1\u05E3 \u05E2\u05D3 \u05E9\u05DE\u05E9\u05D5\u05D5\u05D9\u05DD \u05D0\u05D5\u05EA\u05D5 \u05DC\u05E1\u05DB\u05D5\u05DD \u05D4\u05D4\u05E4\u05E7\u05D3\u05D5\u05EA \u05E9\u05D4\u05DD \u05DE\u05D1\u05D8\u05D7\u05D9\u05DD: \u05DB\u05DE\u05E2\u05D8 10 \u05D8\u05E8\u05D9\u05DC\u05D9\u05D5\u05DF \u05D0\u05D5 10,000 \u05DE\u05D9\u05DC\u05D9\u05D0\u05E8\u05D3 \u05D3\u05D5\u05DC\u05E8.",
	"bank_runs_fdic_content_4": "\u05D4-FDIC \u05D0\u05E4\u05D9\u05DC\u05D5 \u05DE\u05E8\u05D0\u05D4 \u05D1\u05D0\u05EA\u05E8 \u05E9\u05DC\u05D5 \u05E9\u05D9\u05E9 \u05DC\u05D5 \u05DE\u05E1\u05E4\u05D9\u05E7 \u05DB\u05E1\u05E3 \u05D1\u05E7\u05E8\u05DF \u05D4\u05D1\u05D9\u05D8\u05D5\u05D7 \u05E9\u05DC\u05D5 \u05DB\u05D3\u05D9 \u05DC\u05DB\u05E1\u05D5\u05EA \u05E7\u05E6\u05EA \u05D9\u05D5\u05EA\u05E8 \u05DE-1% \u05DE\u05D4\u05D4\u05E4\u05E7\u05D3\u05D5\u05EA.",
	"bank_runs_fdic_content_5": "\u05D1\u05DE\u05E7\u05E8\u05D4 \u05E9\u05DC \u05DB\u05E9\u05DC\u05D5\u05DF \u05D1\u05E0\u05E7 \u05E9\u05D7\u05E8\u05D2 \u05DE\u05E7\u05E8\u05DF \u05D4\u05D1\u05D9\u05D8\u05D5\u05D7 \u05E9\u05DC \u05D4-FDIC, \u05E1\u05D1\u05D9\u05E8 (\u05D0\u05DA \u05DC\u05D0 \u05DE\u05D5\u05D1\u05D8\u05D7) \u05E9\u05DE\u05DE\u05E9\u05DC\u05EA \u05D0\u05E8\u05D4\u05F4\u05D1 \u05EA\u05D3\u05E4\u05D9\u05E1 \u05DB\u05E1\u05E3 \u05DB\u05D3\u05D9 \u05DC\u05E4\u05E6\u05D5\u05EA \u05D0\u05EA \u05D4\u05DE\u05E4\u05E7\u05D9\u05D3\u05D9\u05DD.",
	"bank_runs_fdic_content_6": "\u05D0\u05D1\u05DC \u05D4\u05D3\u05E4\u05E1\u05EA \u05DB\u05E1\u05E3 \u05D2\u05D5\u05E8\u05DE\u05EA \u05DC\u05D0\u05D9\u05E0\u05E4\u05DC\u05E6\u05D9\u05D4, \u05D0\u05D6 \u05D6\u05D4 \u05DC\u05D0 \u05E4\u05EA\u05E8\u05D5\u05DF \u05DE\u05E6\u05D5\u05D9\u05DF.",
	"bank_runs_safe": "\u05D4\u05D0\u05DD \u05D9\u05E9 \u05D1\u05E0\u05E7\u05D9\u05DD \u05E9\u05DC\u05D0 \u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05D1\u05E8\u05D6\u05E8\u05D1\u05D4 \u05D7\u05DC\u05E7\u05D9\u05EA?",
	"bank_runs_safe_content_1": "\u05D7\u05DC\u05E7 \u05DE\u05D4\u05D1\u05E0\u05E7\u05D9\u05DD \u05E0\u05D9\u05E1\u05D5 \u05DC\u05D4\u05D9\u05D5\u05EA '\u05D1\u05E0\u05E7\u05D9\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD' \u05E9\u05DC\u05D0 \u05DE\u05DC\u05D5\u05D5\u05D9\u05DD \u05D0\u05D5 \u05DE\u05E9\u05E7\u05D9\u05E2\u05D9\u05DD \u05D0\u05EA \u05DB\u05E1\u05E4\u05D9 \u05D4\u05DE\u05E4\u05E7\u05D9\u05D3\u05D9\u05DD.",
	"bank_runs_safe_content_2": "\u05DC\u05DE\u05E8\u05D5\u05EA \u05E9\u05D1\u05E0\u05E7\u05D9\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05D0\u05DC\u05D4 \u05DC\u05D0 \u05D4\u05D9\u05D4 \u05E1\u05D9\u05DB\u05D5\u05DF \u05E9\u05DC \u05DE\u05E8\u05D5\u05E6\u05D9\u05DD \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7 \u05D1\u05DB\u05DC\u05DC, \u05D4\u05D1\u05E7\u05E9\u05D5\u05EA \u05E9\u05DC\u05D4\u05DD \u05E0\u05D3\u05D7\u05D5 \u05E2\u05DC \u05D9\u05D3\u05D9 \u05D4\u05E4\u05D3\u05E8\u05DC \u05E8\u05D6\u05E8\u05D1. \u05D6\u05D4 \u05D0\u05D5\u05DE\u05E8 \u05E9\u05D4\u05DD \u05DC\u05D0 \u05D9\u05DB\u05D5\u05DC\u05D9\u05DD \u05DC\u05E4\u05E2\u05D5\u05DC \u05DB\u05D1\u05E0\u05E7\u05D9\u05DD \u05D1\u05D0\u05D5\u05E4\u05DF \u05D7\u05D5\u05E7\u05D9.",
	"bank_runs_safe_content_3": "\u05DE\u05DB\u05D9\u05D5\u05D5\u05DF \u05E9\u05D4\u05DD \u05E0\u05D7\u05E1\u05DE\u05D5 \u05DE\u05E4\u05E2\u05D9\u05DC\u05D5\u05EA, \u05D0\u05D9\u05DF \u05D4\u05D9\u05D5\u05DD \u05D1\u05E0\u05E7\u05D9\u05DD \u05E9\u05DC\u05D0 \u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05D1\u05E8\u05D6\u05E8\u05D1\u05D4 \u05D7\u05DC\u05E7\u05D9\u05EA.",
	"bank_runs_safe_content_4": "\u05DC\u05DE\u05D6\u05DC\u05E0\u05D5, \u05D9\u05E9 \u05D3\u05E8\u05DA \u05DC\u05E6\u05D0\u05EA \u05DE\u05DE\u05E2\u05E8\u05DB\u05EA \u05D4\u05E8\u05D6\u05E8\u05D1\u05D4 \u05D4\u05D7\u05DC\u05E7\u05D9\u05EA \u05E2\u05DC \u05D9\u05D3\u05D9 \u05DB\u05DA \u05E9\u05D0\u05EA\u05D4 \u05D4\u05D1\u05E0\u05E7 \u05E9\u05DC \u05E2\u05E6\u05DE\u05DA. \u05DC\u05D0, \u05D0\u05E0\u05D7\u05E0\u05D5 \u05DC\u05D0 \u05DE\u05D3\u05D1\u05E8\u05D9\u05DD \u05E2\u05DC \u05DC\u05D4\u05D7\u05D1\u05D9\u05D0 \u05DE\u05D6\u05D5\u05DE\u05DF \u05DE\u05EA\u05D7\u05EA \u05DC\u05DE\u05D6\u05E8\u05DF.",
	"bank_runs_safe_content_5": "\u05D7\u05D9\u05E1\u05DB\u05D5\u05DF \u05D1\u05DE\u05D6\u05D5\u05DE\u05DF \u05E2\u05D3\u05D9\u05D9\u05DF \u05E4\u05D2\u05D9\u05E2 \u05DC\u05D0\u05D9\u05E0\u05E4\u05DC\u05E6\u05D9\u05D4.",
	"bank_runs_safe_content_6": "\u05D0\u05E0\u05D7\u05E0\u05D5 \u05DE\u05D3\u05D1\u05E8\u05D9\u05DD \u05E2\u05DC \u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF: \u05DE\u05E2\u05E8\u05DB\u05EA \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05EA \u05D7\u05D3\u05E9\u05D4 \u05E9\u05DE\u05D0\u05E4\u05E9\u05E8\u05EA \u05DC\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05D4\u05D1\u05E0\u05E7 \u05E9\u05DC \u05E2\u05E6\u05DE\u05DA.",
	"bank_runs_protect": "\u05D4\u05D0\u05DD \u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05D9\u05DB\u05D5\u05DC \u05DC\u05D4\u05D2\u05DF \u05E2\u05DC\u05D9 \u05DE\u05DE\u05E8\u05D5\u05E6\u05D9\u05DD \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7?",
	"bank_runs_protect_content_1": "\u05DB\u05DF, \u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05D4\u05D9\u05D0 \u05DE\u05E2\u05E8\u05DB\u05EA \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05EA \u05E9\u05DC \u05E8\u05D6\u05E8\u05D1\u05D4 \u05DE\u05DC\u05D0\u05D4.",
	"bank_runs_protect_content_2": "\u05DE\u05E8\u05D5\u05E6\u05D9\u05DD \u05E2\u05DC \u05D4\u05D1\u05E0\u05E7 \u05D1\u05DC\u05EA\u05D9 \u05D0\u05E4\u05E9\u05E8\u05D9\u05D9\u05DD \u05D1\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05DB\u05DC \u05E2\u05D5\u05D3 \u05D0\u05EA\u05D4 \u05DE\u05D5\u05E9\u05DA \u05D0\u05EA \u05D4\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05E9\u05DC\u05DA \u05DC\u05D0\u05E8\u05E0\u05E7 \u05E9\u05DC\u05DA. \u05D0\u05DC \u05EA\u05E9\u05D0\u05D9\u05E8 \u05D0\u05EA \u05D4\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05E9\u05DC\u05DA \u05D1\u05D1\u05D5\u05E8\u05E1\u05D4 \u05D0\u05D5 \u05D1\u05E2\u05D8\u05D9\u05E4\u05D4 \u05DB\u05DE\u05D5 \u05E7\u05E8\u05DF \u05E1\u05DC \u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF.",
	"bank_runs_protect_content_3": "\u05E2\u05D9\u05D9\u05E0\u05D5 \u05D1\u05DE\u05D3\u05E8\u05D9\u05DA \u05D0\u05E8\u05E0\u05E7\u05D9 \u05D4\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05D4\u05E4\u05E9\u05D5\u05D8 \u05E9\u05DC\u05E0\u05D5 \u05DB\u05D3\u05D9 \u05DC\u05DC\u05DE\u05D5\u05D3 \u05D0\u05D9\u05DA \u05DC\u05DE\u05E9\u05D5\u05DA \u05DC\u05D0\u05E8\u05E0\u05E7 \u05E9\u05DC\u05DA.",
	"bank_runs_protect_content_4": "\u05E2\u05DD \u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF, \u05D0\u05EA\u05D4 \u05E1\u05D5\u05E3 \u05E1\u05D5\u05E3 \u05D9\u05DB\u05D5\u05DC \u05DC\u05E9\u05DC\u05D5\u05D8 \u05D1\u05DB\u05E1\u05E3 \u05E9\u05DC\u05DA."
});

