	"wallets_header": "\u05D0\u05D9\u05DA \u05DC\u05D0\u05D7\u05E1\u05DF \u05D0\u05EA \u05D4\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05E9\u05DC\u05DA \u05D1\u05D1\u05D8\u05D7\u05D4",
