	"lightning_features": "\u05D4\u05E8\u05D1\u05D4 \u05EA\u05DB\u05D5\u05E0\u05D5\u05EA", "lightning_mobile_app": "\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4 \u05DC\u05E0\u05D9\u05D9\u05D3", "lightning_free": "\u05D7\u05D9\u05E0\u05DD \u05DC\u05D7\u05DC\u05D5\u05D8\u05D9\u05DF 100%", "lightning_merchants": "\u05DE\u05E6\u05D5\u05D9\u05DF \u05DC\u05E1\u05D5\u05D7\u05E8\u05D9\u05DD", "lightning_starter": "\u05D0\u05E8\u05E0\u05E7 \u05DE\u05E2\u05D5\u05DC\u05D4 \u05DC\u05DE\u05EA\u05D7\u05D9\u05DC\u05D9\u05DD", "lightning_browser": "\u05DE\u05D1\u05D5\u05E1\u05E1 \u05D3\u05E4\u05D3\u05E4\u05DF", "lightning_custodial": "\u05D0\u05E8\u05E0\u05E7 \u05DE\u05E9\u05DE\u05D5\u05E8\u05E0\u05D9 \u05DC\u05D7\u05DC\u05D5\u05D8\u05D9\u05DF",
	"lightning_cta_hardware": "\u05DE\u05D7\u05E4\u05E9 \u05D0\u05EA \u05DE\u05D3\u05E8\u05D9\u05DA \u05D0\u05E8\u05E0\u05E7\u05D9 \u05D4\u05D7\u05D5\u05DE\u05E8\u05D4 \u05E9\u05DC \u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF?"
